contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 openAmount, uint256 closeAmount) public {
        c.openTake(UFixed18.wrap(openAmount));

        (uint256 makerBefore, uint256 takerBefore) = c.position(address(this));

        bool reverted;
        try c.closeAll(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 makerAfter, uint256 takerAfter) = c.position(address(this));
        bool liquidating = c.isLiquidating(address(this));

        assert(
            !reverted
                ? (makerAfter == 0 && takerAfter == 0 && liquidating)
                : (makerAfter == makerBefore && takerAfter == takerBefore && !liquidating)
        );
    }
}

