contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address account, uint256 amount) public payable {
        require(address(this).balance >= 0, "insufficient balance");

        // Setup: bring c into a live, fully initialized state.
        c.settle();
        c.settleAccount(account);

        // Read before-values through the public surface.
        uint256 makerBefore = c.position(account).maker;
        uint256 takerBefore = c.position(account).taker;
        bool liquidationBefore = c.isLiquidating(account);

        // The deciding call: attempt a maker close, which must leave a position's
        // maker side unchanged whenever the taker side is zero (insufficient liquidity guard).
        bool reverted;
        try c.closeMakeFor(account, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: a reverted close leaves the account's maker position untouched;
        // a successful close never increases the maker position (it either reduces it
        // or leaves it the same when amount is zero).
        if (reverted) {
            assert(c.position(account).maker == makerBefore);
        } else {
            assert(c.position(account).maker <= makerBefore);
            assert(c.isLiquidating(account) == liquidationBefore);
        }
    }
}

