        require(amount <= type(uint256).max, "amount overflow guard");

        // Setup: bring c into a live, fully initialized state.
        c.settle();
        c.settleAccount(account);

        // Read before-value through the public surface.
        UFixed18 makerBefore = c.position(account).maker;

        // The deciding call: attempt a maker close, which must leave a position's
        // maker side unchanged whenever the close reverts, and must never increase
        // the maker side on success.
        bool reverted;
        try c.closeMakeFor(account, UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule over all inputs.
        if (reverted) {
            assert(UFixed18.unwrap(c.position(account).maker) == UFixed18.unwrap(makerBefore));
        } else {
            assert(UFixed18.unwrap(c.position(account).maker) <= UFixed18.unwrap(makerBefore));
        }
    }
}

