contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool newClosed, bool attemptUpdate) public payable {
        require!(address(c) != address(0));

        bool initialClosed = c.closed();
        require(initialClosed == false, "fresh C must not be closed");

        bool updateReverted;
        if (attemptUpdate) {
            try c.updateClosed(newClosed) {
                updateReverted = false;
            } catch {
                updateReverted = true;
            }
            assert(!updateReverted && c.closed() == newClosed || updateReverted && c.closed() == false);
        } else {
            assert(initialClosed == false && c.closed() == false);
        }
    }
}

