contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint128 amount, uint128 closeAmount, uint128 maintenance, uint128 makerFee, uint128 takerFee, uint128 makerLimit) public payable {
        // Setup: initialize the product so that at least oracle version 1 can exist.
        // The test contract is the controller/minter via msg.sender.
        // Build a basic ProductInfo with zero/valid params so nobody can close.
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.VANILLA,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
            data: bytes30(0)
        });
        // Use address zero oracle: likely invalid, but the revert path is intended in the rule below.
        info.oracle = IOracleProvider(address(0));
        info.maintenance = UFixed18.wrap(uint256(maintenance));
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(uint256(makerFee));
        info.takerFee = UFixed18.wrap(uint256(takerFee));
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(uint256(makerLimit));
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        bool initReverted;
        try c.initialize(info) {
            initReverted = false;
        } catch {
            initReverted = true;
        }

        // Read the account's pending taker position through the public pre() getter.
        PrePosition memory prePos = c.pre(address(this));
        UFixed18 pendingTaker = prePos.openPosition.taker;

        // Attempt to close more taker than the account has pending.
        bool closeReverted;
        try c.closeTakeFor(address(this), UFixed18.wrap(uint256(closeAmount))) {
            closeReverted = false;
        } catch {
            closeReverted = true;
        }

        // General rule: for any amount the caller requests to close, either the call
        // succeeds (meaning the amount was within the account's taker position) or it
        // reverts. In all cases the resulting taker position must never be negative,
        // which is observable as the close not succeeding when amount > current taker.
        // Since the only state-changing call in between is closeTakeFor, the final
        // pending taker position read must be the original pending taker minus closeAmount
        // if successful, or unchanged if reverted. We assert the invariant by checking
        // that the post-close taker position is not greater than the pre-close position.
        PrePosition memory postPos = c.pre(address(this));
        UFixed18 postTaker = postPos.openPosition.taker;

        // If close was attempted with amount > pendingTaker, close must have reverted and
        // the post position must equal the pre position. Otherwise, if pendingTaker >= closeAmount,
        // the close must succeed and postTaker must equal pendingTaker - closeAmount (no underflow).
        bool exceeded = uint256(closeAmount) > uint256(UFixed18.unwrap(pendingTaker));
        assert((exceeded && closeReverted && uint256(UFixed18.unwrap(postTaker)) == uint256(UFixed18.unwrap(pendingTaker))) ||
               (!exceeded && !closeReverted && uint256(UFixed18.unwrap(postTaker)) == uint256(UFixed18.unwrap(pendingTaker)) - uint256(closeAmount)));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint128 closeAmount) public payable {
        // Read the account's pending taker position through the public pre(address) getter.
        PrePosition memory prePos = c.pre(address(this));
        UFixed18 pendingTaker = prePos.openPosition.taker;

        // Attempt to close the requested amount of taker.
        bool closeReverted;
        try c.closeTakeFor(address(this), UFixed18.wrap(uint256(closeAmount))) {
            closeReverted = false;
        } catch {
            closeReverted = true;
        }

        // Read the resulting pending taker position.
        PrePosition memory postPos = c.pre(address(this));
        UFixed18 postTaker = postPos.openPosition.taker;

        bool exceeded = uint256(closeAmount) > uint256(UFixed18.unwrap(pendingTaker));

        // General rule: if the request exceeds the pending position the call must revert
        // and the position must be unchanged; otherwise the call must succeed and reduce
        // the pending taker position by exactly closeAmount, never going negative.
        assert(
            (exceeded && closeReverted && uint256(UFixed18.unwrap(postTaker)) == uint256(UFixed18.unwrap(pendingTaker))) ||
            (!exceeded && !closeReverted && uint256(UFixed18.unwrap(postTaker)) + uint256(closeAmount) == uint256(UFixed18.unwrap(pendingTaker)))
        );
    }
}

contract InvMutTest {
    C c;

