    receive() external payable {}

    function run(uint128 closeAmount) public payable {
        require(closeAmount > 0, "amount must be positive");

        // The account has no pending taker position initially.
        PrePosition memory prePos = c.pre(address(this));
        require(UFixed18.unwrap(prePos.openPosition.taker) == 0, "no initial pending taker");

        bool reverted;
        try c.closeTakeFor(address(this), UFixed18.wrap(uint256(closeAmount))) {
            reverted = false;
        } catch {
            reverted = true;
        }

        PrePosition memory postPos = c.pre(address(this));

        // General rule: with zero pending taker, closing any positive amount must not
        // succeed and increase the position; it either reverts or leaves it unchanged.
        assert(reverted || UFixed18.unwrap(postPos.openPosition.taker) == 0);
    }
}

