contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 makerAmount, uint256 takeAmount) public payable {
        // Maker must be substantial enough that the open-take call can succeed for some inputs.
        UFixed18 mk = UFixed18.wrap(makerAmount);
        UFixed18 amt = UFixed18.wrap(takeAmount);

        // Establish the maker position first. This call itself must be a top-level statement.
        c.openMakeFor(address(this), mk);

        // Read pre-values from c via its public surface.
        Position memory makerPos = c.position(address(this));
        PrePosition memory makerPre = c.pre(address(this));

        // Now attempt the deciding call: openTakeFor on the same account.
        bool reverted;
        try c.openTakeFor(address(this), amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // Atomicity: a reverted open-take must not change the account's position.
            Position memory pAfterRevert = c.position(address(this));
            PrePosition memory preAfterRevert = c.pre(address(this));
            assert(
                pAfterRevert.maker == makerPos.maker &&
                pAfterRevert.taker == makerPos.taker &&
                preAfterRevert.openPosition.maker == makerPre.openPosition.maker &&
                preAfterRevert.openPosition.taker == makerPre.openPosition.taker &&
                preAfterRevert.closePosition.maker == makerPre.closePosition.maker &&
                preAfterRevert.closePosition.taker == makerPre.closePosition.taker
            );
        } else {
            // On success, the account must be marked non-liquidation and the product's
            // aggregate open position must reflect the requested taker amount.
            Position memory pAfter = c.position(address(this));
            PrePosition memory preAfter = c.pre(address(this));
            Position memory productOpen = c.pre().openPosition;
            assert(
                !c.isLiquidating(address(this)) &&
                preAfter.openPosition.taker == amt &&
                pAfter.taker == amt &&
                productOpen.taker == amt
            );
        }
    }
}

