        require(makerAmount > 0 && makerAmount <= 1e24, "maker out of bounds");
        require(takeAmount > 0 && takeAmount <= 1e24, "take out of bounds");
        require(closeAmount <= takeAmount, "close exceeds take");

        c.openMake(UFixed18.wrap(makerAmount));
        c.openTake(UFixed18.wrap(takeAmount));

        bool closedBefore = c.isClosed(msg.sender);
        bool reverted;
        try c.closeTake(UFixed18.wrap(closeAmount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool notOverClosedBefore = !closedBefore;
        assert(reverted || notOverClosedBefore || !c.isClosed(msg.sender));
    }

    receive() external payable {}
}

