        // Setup: open make on account to create a maker position
        c.openMakeFor(account, UFixed18.wrap(amount1));

        // Setup: open take on account to create a taker position, making it double-sided
        c.openTakeFor(account, UFixed18.wrap(amount2));

        // Attempt to open more take on the same double-sided account
        bool reverted;
        try c.openTakeFor(account, UFixed18.wrap(amount1)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.pre(account).openPosition.maker > 0 && c.pre(account).openPosition.taker > 0);
    }

    receive() external payable {}
}

