contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        string calldata productName,
        string calldata productSymbol,
        address oracle_
    ) public payable {
        // Before initialization, c must be an uninitialized product with closed() == false.
        bool closedBefore = c.closed();
        UFixed18 maintenanceBefore = c.maintenance();
        bool reverted;

        require(oracle_ != address(0));

        // Read-only observables of an uninitialized product.
        IProduct.ProductInfo memory productInfo = IProduct.ProductInfo({
            name: productName,
            symbol: productSymbol,
            payoffDefinition: c.payoffDefinition(),
            oracle: IOracleProvider(oracle_),
            maintenance: maintenanceBefore,
            fundingFee: c.fundingFee(),
            makerFee: c.makerFee(),
            takerFee: c.takerFee(),
            positionFee: c.positionFee(),
            makerLimit: c.makerLimit(),
            utilizationCurve: c.utilizationCurve()
        });

        try c.initialize(productInfo) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            closedBefore == false &&
            reverted == false &&
            c.closed() == false &&
            keccak256(bytes(c.name())) == keccak256(bytes(productName)) &&
            keccak256(bytes(c.symbol())) == keccak256(bytes(productSymbol))
        );
    }

    receive() external payable {}
}

